from __future__ import annotations

import ast
from dataclasses import dataclass


@dataclass(slots=True, frozen=True)
class ImportedSymbols:
    """Immutable collection of imported module names and their alias mappings."""
    symbols: dict[str, list[str]]


def extract_imports(tree: ast.Module) -> ImportedSymbols:
    """Extract all imported module names and their alias mappings from an AST."""
    symbols: dict[str, list[str]] = {}

    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            module = node.module or ""
            aliases = [alias.name for alias in node.names]
            symbols.setdefault(module, []).extend(aliases)
        elif isinstance(node, ast.Import):
            module = node.names[0].name
            aliases = [alias.name for alias in node.names]
            symbols.setdefault(module, []).extend(aliases)

    return ImportedSymbols(symbols=symbols)
```

### Memory & Portability Guarantees
- **Zero-copy AST parsing**: Avoids parsing string source code into memory.
- **POSIX path normalization**: Guarantees cross-platform portability on Windows and Linux.
- **Immutable dataclass**: Enables safe concurrent symbol collection across multiple threads.
